// Node 2: Validate Input, Normalize Indian Phone & Calculate Month-End Safe Expiry Date
const body = $input.first().json.body || $input.first().json;

const name = String(body.name || body.Name || '').trim();
const email = String(body.email || body.Email || '').trim().toLowerCase();
const rawPhone = String(body.phone || body.Phone || '').trim();
const plan = String(body.plan || body.Plan || 'Monthly').trim();
const joiningDate = String(body.joiningDate || body.Joining_Date || '').trim();
const paymentStatus = String(body.paymentStatus || body.Payment_Status || 'Pending').trim();
const paymentMethod = String(body.paymentMethod || body.Payment_Method || 'UPI').trim();
const whatsappConsent = (body.whatsappConsent === true || String(body.whatsappConsent).toUpperCase() === 'TRUE') ? 'TRUE' : 'FALSE';

// 1. Validate required fields
if (!name || name.length < 2) {
  throw new Error('Validation Error: Full Name is required (min 2 chars).');
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(joiningDate)) {
  throw new Error('Validation Error: Joining_Date must be in YYYY-MM-DD format.');
}

// 2. Normalize Indian Phone Number to 91XXXXXXXXXX
const digits = rawPhone.replace(/\D/g, '');
let tenDigit = digits;
if (digits.length === 12 && digits.startsWith('91')) tenDigit = digits.slice(2);
else if (digits.length === 11 && digits.startsWith('0')) tenDigit = digits.slice(1);

if (!/^[6-9]\d{9}$/.test(tenDigit)) {
  throw new Error(`Validation Error: Invalid Indian mobile number (${rawPhone}). Must be 10 digits starting with 6-9.`);
}
const normalizedPhone = `91${tenDigit}`;

// 3. Resolve Membership Duration in Months
let durationMonths = Number(body.durationMonths || 0);
if (!durationMonths) {
  const p = plan.toLowerCase();
  if (p.includes('year')) durationMonths = 12;
  else if (p.includes('quarter')) durationMonths = 3;
  else durationMonths = 1;
}

// 4. Calculate Expiry_Date with Month-End Clamping (Jan 31 + 1 month -> Feb 28/29)
function addMonthsClamped(dateStr, monthsToAdd) {
  const [year, month, day] = dateStr.split('-').map(Number);
  const totalMonths = (month - 1) + Number(monthsToAdd);
  const targetYear = year + Math.floor(totalMonths / 12);
  const targetMonthIndex = totalMonths % 12;
  const maxDaysInTargetMonth = new Date(Date.UTC(targetYear, targetMonthIndex + 1, 0)).getUTCDate();
  const clampedDay = Math.min(day, maxDaysInTargetMonth);
  return `${targetYear}-${String(targetMonthIndex + 1).padStart(2, '0')}-${String(clampedDay).padStart(2, '0')}`;
}

const expiryDate = addMonthsClamped(joiningDate, durationMonths);
const memberId = `GYM-${Date.now().toString().slice(-6)}`;

return [{
  json: {
    Member_ID: memberId,
    Name: name,
    Phone: normalizedPhone,
    Email: email,
    Plan: plan,
    Duration_Months: durationMonths,
    Joining_Date: joiningDate,
    Expiry_Date: expiryDate,
    Payment_Status: paymentStatus,
    Payment_Method: paymentMethod,
    WhatsApp_Consent: whatsappConsent,
    Last_Reminder_Date: '',
    Member_Status: 'Active'
  }
}];

